text:
.form-selection {
  position: sticky;
  inset-block-start: 0;
  display: flex;
  flex-direction: column;
  gap: var(--hub-space-large);
  background-color: var(--color-surface-base);
  padding: var(--hub-space-medium);
  border: 1px solid var(--color-primary-default);
  border-radius: 10px;

  &.credentials-confirmation {
    inline-size: fit-content;
    min-inline-size: 380px;
    margin-inline: auto;
  }

  &.config-selection {
    gap: 0;
    &.single {
      gap: var(--hub-space-medium);
    }

    &.is-showing-shared-config .shared-config-item,
    &:not(.is-showing-shared-config) .config-common {
      display: none;
    }
  }

  & .selection-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-rows: auto;
    gap: var(--hub-space-medium);

    & .config-column {
      display: flex;
      flex-direction: column;
      gap: var(--hub-space-medium);

      .credentials-confirmation & {
        gap: var(--hub-space-large);
        padding-block: 15px;
      }
    }

    .credentials-confirmation & {
      padding-inline: 15px;
    }

    .single & {
      display: block;
    }
  }
